content.content:
560	    .hero-stage{justify-content:flex-end;padding-bottom:10svh;}
561	    .hero-plate{aspect-ratio:4 / 5;
562	      width:min(calc(100% - 2 * var(--rail-x)),calc(48svh * 4 / 5));}
563	    .hero-sub{text-align:left;margin-left:var(--rail-x);margin-right:var(--rail-x);
564	      padding-right:0;}
565	  }
566	
567	  /* ============================================================ under heron
568	     Kolumnfördelningen är målbildens: vänster = blå tes -> Calyx -> pris,
569	     höger = jätterubrik + liggare -> Hōrai. Grunddriften går i tre stopp,
570	     eftersom grunden ÄR sidan och inte en dekoration. */
571	  .stagger{position:relative;display:flex;align-items:stretch;
572	    gap:clamp(20px,4vw,58px);
573	    /* PLAN 017 C: seamen mot pinnen var en slits (padding-top 0, ärvt
574	       från "flow direkt efter pin"), inte ett författat mellanrum. H-05
575	       (a): kontinuerlig grund kräver >=160px luft. */
576	    padding:clamp(160px,18vh,200px) clamp(16px,3vw,40px) 0;}
577	  .col{min-width:0;flex:1 1 50%;display:flex;flex-direction:column;}
578	  /* PLAN 017 B: paired columns never top-align (house physics); spalterna
579	     stod båda vid samma y innan denna rad. */
580	  .col-right{padding-top:clamp(96px,12vh,140px);}
581	  /* PLAN 017 C: H-05 (a), samma 160-200px golv mellan paneler i en spalt. */
582	  .col > * + *{margin-top:clamp(160px,18vh,200px);}
583	  /* PLAN 012 + 017 (samma block, 017 körs först): berättelsens ordning
584	     s4->s7 (tes->Calyx->jätterubrik/liggare->Hōrai->pris) upplöst med
585	     display:contents så panelerna blir direkta flexbarn till .stagger och
586	     kan sorteras med order. .col > * + * MATCHAR fortfarande under 900
587	     (selektorn läser DOM, inte layout; Astra loop 1 fix 1) - nollas här,
588	     gap (höjt till H-05:s 64-96px mobilgolv) bär avståndet ensamt.
589	     .col-right:s padding-top (017 B) nollas: den är en desktop-only
590	     spaltförskjutning, fel som ett flexbarn-attribut här. */
591	  @media (max-width:900px){
592	    /* PLAN 032 B, H-05: 84px rå grund mellan panelerna vid 390x844 (10vh av
593	       844), under 96px-golvet. */
594	    .stagger{flex-direction:column;gap:clamp(96px,12vh,120px);padding:0 0 0;}
595	    .col{display:contents;}
596	    .col > * + *{margin-top:0;}
597	    .col-right{padding-top:0;}
598	    .panel-thesis{order:1;}
599	    .calyx-fig{order:2;}
600	    .panel-giant{order:3;}
601	    .horai-fig{order:4;}
602	  }
603	  /* Ett paddingmått för varje panels egen inre höjd, ärvt från V3b, så att
604	     ingen panel klampar mot sitt eget tak. */
605	  .panel-pad{--panel-pad-y:clamp(28px,4.6vw,52px);}
606	
607	  /* Alla kickers som INTE är monoregister. Monobudgeten är fyra etiketter på
608	     hela sidan och de är: kortbaksidans kicker, kortbaksidans tjänsterad,
609	     Exempelsida-kickern i tesen, och liggarens siffror. Allt annat som ser ut
610	     som en etikett sätts i Public Sans 600. */
611	  .kicker-sans{font-family:var(--font);font-weight:600;font-size:11px;
612	    letter-spacing:.16em;text-transform:uppercase;}
613	
614	  /* ---------------------------------------------------------- s4, blå tes
615	     Sidans enda mättade färgblock, och accentens FÖRSTA av två förekomster.
616	     data-sc-drift tar grunden mot #123f68 medan akten är på skärmen: samma
617	     roll, mörkare stopp, inte en andra accent. */
618	  .panel-thesis{--pad-i:clamp(24px,4vw,48px);
619	    background:var(--c-accent);color:var(--c-white);
620	    padding:var(--panel-pad-y) var(--pad-i);overflow:visible;
621	    /* PLAN 051 fix 5 (R4, Astra material_fixes #5): panelen täckte bara
622	       ~46% av viewportens höjd, mot Astras 80%-mål ("panelen ska äga
623	       viewporten"). Skopad min-height (bara denna panel, inte det delade
624	       --panel-pad-y-tokenet som även styr andra paneler) med flex-
625	       centrering så den större rubriken/bilden fyller ut, inte bara
626	       sträcker paddingen. */
627	    min-height:80svh;display:flex;flex-direction:column;justify-content:center;}
628	  /* PLAN 049 fix 6 (Astra material_fixes #6, P03). 28ch är STÖRRE än vad
629	     ,6fr ensam ger vid den här spaltbredden (519px kombinerat), så
630	     minimum vann och åt bildens spalt (249px, uppmätt 20,6%vw i stället
631	     för den avsedda fördelningen). 14ch ger text sin egen spalt utan att
632	     äta bildens.
633	     AVVIKELSE, PLAN 050 fix 1 (R3): 14ch (135px) visade sig vara ETT
634	     GOLV SOM ALLTID VANN (135px vid 1024/1280/1440/1920, `.5fr` gav
635	     aldrig mer), inte ett minimum som sällan nåddes - rubriken "DET
636	     FÖRSTA INTRYCKET ÄR DIGITALT." delades mitt i ord (DET/FÖRST/A/...)
637	     vid alla fyra breddar. Bytt till ett pixelgolv (`ch` på grid-
638	     containern löste inte ut mot styckets egen fontstorlek) uppmätt att
639	     ge >=36ch av stycket och <=4 rubrikrader vid 768-1920 (se NOTES §
640	     V3d R3). */
641	  .thesis-grid{position:relative;z-index:2;display:grid;
642	    /* PLAN 051 fix 5 (R4): rubriken höjd (38->65px, ovan) delade "INTRYCKET"
643	       vid 1440/1920 inom R3:s 340px-golv - samma klass regression som R3
644	       själv fixade, nu vid den NYA fontstorleken. Golvet höjt igen, mätt
645	       mot 0 delade ord vid alla fem breddar (se NOTES § V3d R4). */
