.panel-giant{background:var(--bg);color:var(--ink);
  padding:var(--panel-pad-y) clamp(24px,5cqw,48px) clamp(28px,8cqw,84px);
  container-type:inline-size;
  /* PLAN 023, R6. Fönstret ankrat i liggarens EGET läge i stället för
     aktens: perf-rapporten mätte tråden scaleY 0->1 löpa medan
     liggaren fortfarande stod djupt under viewportens överkant -
     tråden var färdigritad innan liggaren var läsbar (H-25).
     AVVIKELSE från planens 0,62/0,95 (steg 2 kräver ommätning och
     justering om talen skiljer mer än 0,05, vilket de gjorde här):
     egen bisektionssökning i R6-läget gav ps 0,364 vid liggarens
     överkant +600px (scrollY 2748) och ps 0,679 vid +90px
     (scrollY 3258) - start 0,364, bredd 0,315.
     AVVIKELSE, PLAN 051 fix 2 (R4, Astra material_fixes #2): slutvärdet
     0,679 mättes FÖRE R2:s margin-top:820px (rad ~918) sköt upp panelens
     naturliga position - full bredd nåddes först vid ps där rubriken
     redan skurits av (uppmätt scrollY 4400+, h1Bottom negativ). Ny
     bisektion mot AKTUELL geometri: ps 0,4498 vid panelens top=100px
     (scrollY 4050) - hela rubriken fortfarande i viewporten. Start
     oförändrad (0,364, redan tuned mot tesens svans, R2/R3), bredd
     krympt 0,315->0,086 så scrub=1 exakt vid detta ps. */
  --scrub:clamp(0,calc((var(--sc-ps,0) - 0.364) / 0.086),1);}
.giant{font-family:var(--f-display);font-weight:700;
  /* PLAN 030: 6rem (96px, plan 014/T-5) kräver en spalt >= 606px; den
     faktiska är 555px (651 - 2*48), så ordet VARUMÄRKE. (601px) kapades
     mitt i (R7, lead). R7:s hyphens:auto-avvikelse gav en riktig
     stavelsedelning i just DEN körningen ("VARU-MÄRKE", 3 rader,
     bekräftat R7), men planen (arkitekten, loop 2) mätte att Chrome på
     Windows saknar en svensk ordlista och inte kan garantera en
     hyphens:auto-brytning över webbläsare/plattform. Ett låst ord får
     aldrig delas, så hyphens:manual (ingen brytning alls, ingen &shy;)
     tar bort beroendet av en ordlista som inte kan garanteras; 88px vid
     -0,04em mäter 542px och håller ordet helt utan att någon delning
     behövs (loop 2, synth3: 1 rect, 3 rader, mätt här på nytt: 88px, 3
     rader). */
  font-size:clamp(2.1rem,7.4vw - 18px,5.5rem);line-height:.96;letter-spacing:-.04em;
  text-transform:uppercase;text-wrap:balance;overflow-wrap:anywhere;min-width:0;
  hyphens:manual;
  transform-origin:left center;}
/* Skalan körs bara när JS finns. Utan JS är --sc-ps 0 och en ogated regel
   hade låst rubriken på 0,92 för alltid. Ingen permanent will-change: den
   raden var en av F-013:s fyra vilande promoveringar. */
/* PLAN 053 fix 4 (R6, Astra material_fixes #4), ersätter ovanstående.
   88px (basclampens 5,5rem-tak) var mindre än kapitelrubrikens 103,68px
   - jätten ska vara sidans starkaste ögonblick efter heron. transform:
   scale() var fel verktyg för att nå dit: den ändrar bara den MÅLADE
   storleken, aldrig layouten - ordbrytningen (VARUMÄRKE, PLAN 030) hade
   förblivit låst vid 88px:s redan uppmätt säkra marginal oavsett
   skalvärde, så en riktig font-size-höjning var varken farligare eller
   dyrare, bara mätbar med samma verktyg som allt annat (getComputedStyle
   ser en transform-skala, inte en font-size). Bunden till --scrub (raden
   ovanför, samma variabel som redan styr PLÅTENS breddökning
   margin-left/width, :951) i stället för det tidigare --sc-ps: vid
   scrub=0 (plåtens smala 555px-startläge, samma spalt PLAN 030 mätte
   ordbrytningen mot) är storleken oförändrad 88px - känd säker marginal,
   rörd inte. Vid scrub=1 (den bredare, urskrivna plåten, >=1189px) läggs
   1,75rem (28px) till: 88+28=116px, 12px marginal över 110px-golvet.
   Skopat till >=901px (samma brytpunkt som .panel-giant:s bleed, :947) -
   under den breddpunkten sker ingen bleed och basclampen (redan
   verifierad ordbrytningsfri vid 768) rörs inte alls. */
@media (min-width:901px){
  .js .giant{font-size:calc(clamp(2.1rem,7.4vw - 18px,5.5rem) + var(--scrub,0) * 1.75rem);}
}
.giant-sub{max-width:46ch;font-size:var(--body-r5);
  color:rgba(22,20,15,.68);margin-top:1.1rem;}

/* PLAN 048 D. Jätten på kortets material: svart plåt, papperets bläck,
   samma hårlinjekant som plåten i heron. Tokenbyte som i C. */
#giant-section{
  --bg: var(--c-black); --ink: var(--c-paper);
  --c-line-on-paper: var(--hairline-dark);
  border:1px solid var(--frame-line);}
/* PLAN 049 fix 6 (Astra material_fixes #6, P04). Ett bleed vänsterut,
   samma teknik som .thesis-figure redan använder (negativ margin +
   motsvarande breddökning), läsande jättens EGEN --scrub (redan
   beräknad två rader ovan ur samma akts --sc-ps, ingen ny variabel).
   margin-top höjt (270->820) efter P03: en obledad tes (bredare i
   denna runda, se .thesis-figure) och en obledad jätte delade skärm
   medan tesens svans fortfarande syntes - rubriken skar rakt genom
   tesbildens kant (skärmbild, scrollY 3600). 820px håller jätten
   osynlig tills tesen rullat bort helt (scrollY ~3900). 44vw (höjt
   från 38) så bredden hinner över 80%vw INNAN rubriken (h1.giant, inte
   .giant-head-omslaget som även räknar in undertexten) rullar ur
   synfältet - uppmätt scrollY 4330: rubrik fortfarande synlig
   (h1Bottom +39px), bredd 82%vw. Ingen kollision tes/rubrik i hela
   övergångsspannet 3200-4300 (uppmätt, rect-overlap X och Y). */
@media (min-width:901px){
  .panel-giant{
    margin-top:820px;
    margin-left:calc(-1 * var(--scrub) * 44vw);
    width:calc(100% + var(--scrub) * 44vw);}
}
#giant-section .giant-sub,#giant-section .ledger-body p{
  color:color-mix(in srgb, var(--c-paper) 72%, var(--c-black));}
#giant-section .ledger-num{
  color:color-mix(in srgb, var(--c-paper) 62%, var(--c-black));}

/* Liggaren. Ordscrubben och den självritande tråden läser --sc-ps.
   Tråden ritas i bläck, aldrig i accenten: låset förbjuder accenten här. */
.ledger-wrap{position:relative;margin-top:clamp(28px,4vw,48px);
  padding-left:clamp(22px,3.2vw,40px);}
.thread{position:absolute;left:0;top:.35em;bottom:6px;width:2px;
  background:var(--c-line-on-paper);}
/* Vilotillståndet är det FÄRDIGA tillståndet: utan JS, före montering och i
   varje läge där scrubben inte armerats står tråden fylld och orden i full
   opacitet. Först .is-scrubbed kopplar in progressen. */
.thread-fill{position:absolute;left:0;top:0;width:2px;height:100%;
  background:var(--ink);transform-origin:top center;transform:scaleY(1);}
.is-scrubbed .thread-fill{transform:scaleY(var(--scrub));}
.ledger{border-top:1px solid var(--c-line-on-paper);}
.ledger-row{display:grid;grid-template-columns:36px 1fr;gap:12px 22px;
  padding:clamp(.8rem,3cqw,1.75rem) 0;
  border-bottom:1px solid var(--c-line-on-paper);}
.ledger-num{font-family:var(--f-mono);font-weight:400;font-size:12px;
  letter-spacing:0;color:rgba(22,20,15,.62);padding-top:.2em;}
.ledger-body h3{font-family:var(--f-display);font-weight:700;font-size:1.15rem;
  letter-spacing:-.01em;text-transform:uppercase;}
.ledger-body p{max-width:56ch;font-size:var(--body-r5);
  color:rgba(22,20,15,.68);margin-top:.4rem;}
/* Ordscrubben utan en enda skrivning per bildruta. Varje ord får sitt index
   --i och radens ordantal --n EN gång vid montering; opaciteten är sedan en
   ren CSS-funktion av --scrub, som ärvs från akten. Fronten --scrub * --n
   vandrar genom orden och varje ord tänds när fronten passerar det.
   Alternativet, att skriva opacity på varje ord varje bildruta, är exakt den
   kostnad F-013 mätte upp som långa tasks. */
/* A11Y-FYND R3, axe `color-contrast`, 35 noder: den första versionen scrubbade
   OPACITET från .14 till 1. Vid varje viloläge under scrubben låg då en del av
   orden på 14 % och var oläsliga, och axe hade rätt. Räknat: golvet måste upp
   till ungefär 0,88 opacitet för att nå 4,5:1 mot papperet, och då finns ingen
   effekt kvar. En opacitetsscrubb på brödtext KAN alltså inte klara AA.
   Devicen är därför additiv i stället för subtraktiv: orden går från sidans
   egen dämpade bläckton till full bläckton. Båda ändarna är läsbara,
   6,3:1 respektive 18:1, och ögat läser fortfarande att fronten tänder dem. */
/* PLAN 028 C (loop 2 profiling): 60 <span class="w"> med egna --i/--n och
   color-mix per ord kostade 2,10ms per --sc-ps-skrivning på jätten (synth3).
   Samma två valörer (62% -> 100% bläck), samma --scrub, som EN gradient per
   textblock i stället: 0,84ms, sex element i stället för 60. 100deg låter
   fronten löpa i läsriktning genom ett flerradigt stycke. */
.is-scrubbed .scrub-text h3,.is-scrubbed .scrub-text p{
  --edge:calc(var(--scrub) * 130%);
  background-image:linear-gradient(100deg,
    var(--ink) 0 calc(var(--edge) - 12%),
    color-mix(in srgb,var(--ink) 62%,var(--bg)) calc(var(--edge) + 12%) 100%);
  -webkit-background-clip:text;background-clip:text;color:transparent;}
@container (max-width:360px){ .ledger-row{grid-template-columns:1fr;} }
@media (max-width:900px){ .ledger-row{grid-template-columns:1fr;} }

/* ---------------------------------------------------------- s6, Hōrai */
.horai-fig{flex:1;}
.horai-wrap{min-height:80dvh;background:var(--invert);
  content-visibility:auto;}

input.new_string:
/* PLAN 054 steg 2/5, river hela jättesektionen: .panel-giant, .giant,
   .giant-sub, #giant-section, .ledger-wrap, .thread*, .ledger, .ledger-row,
   .ledger-body, .is-scrubbed-mekaniken, @container. Den låsta raden
   "VI BYGGER ERT VARUMÄRKE." lever nu som tesbandets femte mening (§
   tesbandet ovan); "Webbdesign, design och system. Allt på ett ställe."
   lever som .process-locked i ridån (nedan); Design/Utveckling/System
   står redan på kortets baksida. .ledger-num behålls (processtegens
   siffror använder den bara klassen, se #process .ledger-num nedan). */
.ledger-num{font-family:var(--f-mono);font-weight:400;font-size:12px;
  letter-spacing:0;color:rgba(22,20,15,.62);padding-top:.2em;}

/* ---------------------------------------------------------- exempelcase
   PLAN 054 steg 4. Ersätter "Hur vi tänker": kapitel + Calyx (text
   vänster/sajt höger) + brygga + Hōrai (spegelvänt). Ramarna skrollas
   INIFRÅN (contentWindow.scrollTo i JS), aldrig transformerade - "en
   ram får aldrig klippas med clip-path", stagen själv glider in. */
.cases-chapter{background:var(--bg);color:var(--ink);min-height:100svh;display:flex;
  flex-direction:column;justify-content:center;padding:clamp(72px,12svh,120px) var(--rail-x);}
.cases-title{font-family:var(--f-display);font-weight:700;
  font-size:clamp(3.5rem,7.2vw,7.5rem);line-height:.95;letter-spacing:-.03em;
  max-width:14ch;padding-top:.6rem;
  --edge:calc(var(--sc-ps,0) * 260%);background-image:linear-gradient(100deg,
    var(--ink) 0 calc(var(--edge) - 12%),color-mix(in srgb,var(--ink) 62%,var(--bg)) calc(var(--edge) + 12%) 100%);
  -webkit-background-clip:text;background-clip:text;color:transparent;}
.cases-lead{font-size:1.25rem;line-height:1.5;max-width:44ch;margin-top:clamp(20px,3svh,32px);
  color:color-mix(in srgb,var(--ink) 80%,var(--bg));}
.case-bridge{background:var(--c-black);color:var(--c-paper);min-height:100svh;display:grid;
  place-content:center;padding:clamp(72px,12svh,120px) var(--rail-x);
  border-top:1px solid var(--frame-line);}
.bridge-title{font-family:var(--f-display);font-weight:700;
  font-size:clamp(2.5rem,5vw + .5rem,5.5rem);line-height:.98;letter-spacing:-.02em;max-width:18ch;}
.bridge-p{font-size:1.25rem;line-height:1.5;max-width:44ch;margin-top:clamp(20px,3svh,32px);
  color:color-mix(in srgb,var(--c-paper) 80%,var(--c-black));}

/* Casen: pinnad stage, text och sajt delar skärmen 5/7. Ramen möter
   viewportens kant (gridbrott). */
.case--calyx{--bg:var(--bg);--ink:var(--ink);}
.case--horai{--bg:var(--c-black);--ink:var(--c-paper);--c-line-on-paper:var(--hairline-dark);}
.case-stage{background:var(--bg);color:var(--ink);display:grid;
  grid-template-columns:minmax(0,5fr) minmax(0,7fr);column-gap:clamp(24px,4vw,64px);
  padding-block:clamp(24px,4svh,40px);}
.case--calyx .case-text{grid-column:1;padding-left:var(--rail-x);}
.case--calyx .case-fig{grid-column:2;}
.case--horai .case-fig{grid-column:1;grid-row:1;}
.case--horai .case-text{grid-column:2;grid-row:1;padding-right:var(--rail-x);}
.case--horai .case-stage{grid-template-columns:minmax(0,7fr) minmax(0,5fr);}
.case-fig{min-width:0;display:flex;flex-direction:column;}
.case-wrap{flex:1;min-height:0;border:1px solid var(--c-line-on-paper);}
.case--calyx .case-wrap{border-right:0;}
.case--horai .case-wrap{border-left:0;}
.case-text{display:flex;flex-direction:column;justify-content:center;min-width:0;}
.case-title{font-family:var(--f-display);font-weight:700;
  font-size:clamp(3.5rem,7.2vw,7.5rem);line-height:.95;letter-spacing:-.03em;margin-top:12px;}
.case-steps{list-style:none;margin:clamp(28px,5svh,48px) 0 0;padding:0;display:grid;}
.cs{grid-area:1/1;min-width:0;}
.cs h3{font-family:var(--f-display);font-weight:700;font-size:clamp(1.5rem,2.2vw,2rem);
  line-height:1.05;letter-spacing:-.01em;text-transform:uppercase;}
.cs p{font-size:clamp(1.0625rem,1.4vw,1.25rem);line-height:1.55;max-width:36ch;margin-top:.7rem;
  color:color-mix(in srgb,var(--ink) 80%,var(--bg));}
/* Samma springa som tesens .ts (--in/--out/clip-path/transform/letter-
   spacing), N ur sektionens egen --n (Calyx 5, Hōrai 6). */
.case--calyx{--n:5;} .case--horai{--n:6;}
.js .cs{--a:calc(var(--i) / var(--n));--b:calc((var(--i) + 1) / var(--n));--f:.04;
  --in:clamp(0,calc((var(--sc-ps,0) - var(--a) + var(--f) / 2) / var(--f)),1);
  --out:clamp(0,calc((var(--sc-ps,0) - var(--b) + var(--f) / 2) / var(--f)),1);
  clip-path:inset(calc(var(--out) * 100%) 0 calc((1 - var(--in)) * 100%) 0);
  transform:translateY(calc((1 - var(--in)) * .55em - var(--out) * .55em));
  letter-spacing:calc(-.01em + (1 - var(--in)) * .06em);}
.js .cs:first-child{--in:1;} .js .cs:last-child{--out:0;}
/* Stegskenan: stegens rubriker i 13px, det aktiva i fullt bläck. */
.case-rail{display:flex;flex-wrap:wrap;gap:6px 18px;margin-top:clamp(28px,5svh,48px);
  padding-top:12px;border-top:1px solid var(--c-line-on-paper);
  font-size:13px;font-weight:600;letter-spacing:.04em;}
.case-rail span{color:color-mix(in srgb,var(--ink) calc(62% + 38% * var(--on,0)),var(--bg));}
.js .case-rail span{--on:clamp(0,calc(1 - abs((var(--sc-ps,0) - (var(--i) - .5) / var(--n)) * (2 * var(--n))) + 1),1);}
@media (max-width:767px){
  .case-stage,.case--horai .case-stage{grid-template-columns:minmax(0,1fr);
    grid-template-rows:52svh minmax(0,1fr);padding:0 0 clamp(16px,3svh,24px);}
  .case .case-fig{grid-column:1;grid-row:1;}
  .case .case-text{grid-column:1;grid-row:2;justify-content:flex-start;
    padding:clamp(16px,3svh,24px) var(--rail-x) 0;}
  .case-wrap,.case--calyx .case-wrap,.case--horai .case-wrap{border:0;
    border-bottom:1px solid var(--c-line-on-paper);}
  .case-text > .kicker-sans{display:none;}
  .case-title{font-size:clamp(2rem,9vw,2.5rem);margin-top:0;}
  .case-steps{margin-top:14px;}
  .cs h3{font-size:1.375rem;} .cs p{font-size:1rem;max-width:none;}
  .case-rail{display:none;}
}

