#p-open-rect,#p-live-img{x:8px;y:20px;width:304px;height:171px;}
/* Måttlinjen och siffrorna (nedan, MOBILE_TEXT) följer samma +6/-4 px-
   offset mot öppningens nya underkant (191) som de hade mot den gamla
   (280) - själva mönstret rörs inte, bara talen räknas om. */
#p-dim-width{d:path("M0 197 H320");}
#p-lead-169{d:path("M304 68 L296 60 H200");}
#p-dot-169{cx:304px;cy:68px;}
/* PLAN 053 fix 1 (R6, Astra material_fixes #1). Revisionsfältet stod
   kvar på sin FÖR-R5-position (y16..52, en tre-radig ISO 7200-stapel
   ärvd från innan mobilen fick ett eget enradigt fält) - efter R5:s
   nya öppning (y20..191) hamnade hela stapeln INUTI fotot och korsade
   Calyx navigation. Flyttat till den fria remsan OVANFÖR öppningen
   (y0..20, tom på både R5:s och denna sidans geometri) och krympt
   till samma enradiga 32x16-box som skrivbordets (846..876,2..18,
   rad ~1929) redan använder - samma mönster, mobilens egna mått. */
#p-title{d:path("M280 2 H312 V18 H280 Z");}
#p-rev{x:280px;y:2px;width:32px;height:16px;}
