import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

async def measure(pg, width, sel):
    await pg.set_viewport_size({"width": width, "height": 900})
    await pg.wait_for_timeout(150)
    data = await pg.evaluate('''(sel) => {
      const results = [];
      document.querySelectorAll(sel).forEach(el => {
        const text = el.textContent.trim();
        if (!text) return;
        let splitWord = null;
        const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
        let node;
        while (node = walker.nextNode()) {
          const t = node.textContent;
          let idx = 0;
          for (const w of t.split(/(\\s+)/)) {
            if (w.trim().length > 1 && !/\\s/.test(w)) {
              const r = document.createRange();
              r.setStart(node, idx);
              r.setEnd(node, idx + w.length);
              const wrects = r.getClientRects();
              if (wrects.length > 1) {
                const tops = new Set([...wrects].map(x => Math.round(x.top)));
                if (tops.size > 1) { splitWord = w; }
              }
            }
            idx += w.length;
          }
        }
        results.push({sel: el.className || el.tagName, text: text.slice(0,30), splitWord});
      });
      return results;
    }''', sel)
    return data

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        pg = await browser.new_page()
        for attempt in range(5):
            try:
                await pg.goto(URL, wait_until="load", timeout=15000)
                break
            except Exception:
                if attempt==4: raise
        SEL = 'h1,h2,h3,.ts,.case-title,.cs h3,.cases-title,.bridge-title,.process-title,.process-step-title,.thesis-headline'
        for w in [768, 1024, 1280, 1440, 1920]:
            d = await measure(pg, w, SEL)
            any_split = False
            for r in d:
                if r["splitWord"]:
                    any_split = True
                    print(w, "<<< SPLIT", r["sel"], r["text"], r["splitWord"])
            if not any_split:
                print(w, "clean,", len(d), "elements checked")
        await browser.close()

asyncio.run(main())
EOF

